  uv += dir * ring * 0.028 * (0.6 + 0.4 * sin(t * 3.2));
  uv.x += sin(uv.y * 26.0 + t * 1.5) * 0.004 * inside;
  uv.y += cos(uv.x * 21.0 + t * 1.2) * 0.0032 * inside;

